"""Second question types for Statistics units 6–12 (the WeBWorK OPL gap-fill objectives): reverses (sample size from a margin,
parameter from a probability), neighbouring moments, and the same model asked about another quantity."""
from opl_dsl import Q

FILE, FRAMEWORK = "st-second-types", "statistics"
MC = ["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"]
n = lambda v: f"nsimplify({v})"
T = "Symbol('t')"
PHI = "(1 + erf(({z})/sqrt(2)))/2"


def facts(name, skill, rows, explain):
    return Q(name, skill, "{{q}}", pace="recall", cases=[{"q": q, "o1": a, "o2": b, "o3": c, "o4": d} for q, a, b, c, d in rows],
             choice=MC, correct="0", verify="authored", explain=explain)


